    html: "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>秒表 | EduToolbox · 课堂秒表计时<\/title>\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E%F0%9F%8E%93%3C/text%3E%3C/svg%3E\">\n<link rel=\"stylesheet\" href=\"stopwatch.css\">\n<link rel=\"stylesheet\" href=\"../../assets/css/tool-common.css\">\n<\/head>\n<body>\n\n<!-- 主体秒表区：左侧大字显示 + 右侧计次列表 -->\n<main class=\"container\">\n  <!-- 时间显示与控制 -->\n  <section class=\"stage\" id=\"stage\">\n    <!-- 舞台右上角工具栏：⛶ 全屏（由 assets/js/tool-stage-toolbar.js 接管） -->\n    <div class=\"stage-toolbar\">\n      <button type=\"button\" class=\"icon-btn\" id=\"fullscreenBtn\" title=\"全屏\">⛶<\/button>\n    <\/div>\n\n    <div class=\"time-display\" id=\"display\" aria-live=\"polite\">\n      <span class=\"time-main\">00:00<\/span><span class=\"time-ms\">.000<\/span>\n    <\/div>\n    <div class=\"status\" id=\"status\">准备就绪<\/div>\n\n    <div class=\"controls\">\n      <button class=\"btn btn-start\" id=\"startBtn\" type=\"button\">开始<\/button>\n      <button class=\"btn btn-lap\" id=\"lapBtn\" type=\"button\" disabled>🚩 计次<\/button>\n      <button class=\"btn btn-reset\" id=\"resetBtn\" type=\"button\">↺ 重置<\/button>\n    <\/div>\n\n    <div class=\"key-hint\">\n      <kbd>Space<\/kbd> 开始/暂停 · <kbd>L<\/kbd> 计次 · <kbd>R<\/kbd> 重置\n    <\/div>\n  <\/section>\n\n  <!-- 计次记录列表 -->\n  <aside class=\"laps-panel\" id=\"lapsPanel\">\n    <div class=\"laps-header\">\n      <h3 class=\"laps-title\">计次记录<\/h3>\n      <button class=\"iconbtn\" id=\"exportBtn\" type=\"button\" disabled title=\"导出为 CSV 文件\">⬇ 导出 CSV<\/button>\n    <\/div>\n    <ul class=\"laps-list\" id=\"lapsList\">\n      <li class=\"state state--list-item state--empty\"><div class=\"state-icon\">⏱️<\/div><div class=\"state-title\">暂无计次记录<\/div><\/li>\n    <\/ul>\n  <\/aside>\n<\/main>\n\n<script src=\"../../assets/js/frame-bridge.js\"><\/script>\n<script src=\"../../assets/js/tool-stage-toolbar.js\"><\/script>\n<script src=\"stopwatch.js\"><\/script>\n<\/body>\n<\/html>\n",
